use std::{
    collections::HashMap,
    fmt,
    panic::{RefUnwindSafe, UnwindSafe},
    sync::Arc,
};

use {
    grep_matcher::{ByteSet, LineTerminator, Match, Matcher, NoError},
    regex_automata::{
        meta::Regex, util::captures::Captures, util::pool::Pool, Input,
        PatternID,
    },
};

use regex_syntax::hir::{self, Hir, HirKind};

use crate::{
    config::{Config, ConfiguredHIR},
    error::{Error, ErrorKind},
    matcher::RegexCaptures,
};

type PoolFn =
    Box<dyn Fn() -> Captures + Send + Sync + UnwindSafe + RefUnwindSafe>;

/// A matcher for implementing "word match" semantics.
pub(crate) struct WordMatcher {
    /// The regex which is roughly `(?:^|\W)(<original pattern>)(?:$|\W)`.
    regex: Regex,
    /// The HIR that produced the regex above. We don't keep the HIR for the
    /// `original` regex.
    ///
    /// We put this in an `Arc` because by the time it gets here, it won't
    /// change. And because cloning and dropping an `Hir` is somewhat expensive
    /// due to its deep recursive representation.
    chir: Arc<ConfiguredHIR>,
    /// The original regex supplied by the user, which we use in a fast path
    /// to try and detect matches before deferring to slower engines.
    original: Regex,
    /// A map from capture group name to capture group index.
    names: HashMap<String, usize>,
    /// A thread-safe pool of reusable buffers for finding the match offset of
    /// the inner group.
    caps: Arc<Pool<Captures, PoolFn>>,
    ascii_word: [bool; 256],
    unicode_word_mode: bool,
    ascii_word_low: u8,
    ascii_word_high: u8,
    connector_byte: u8,
    window_lead: usize,
    window_trail: usize,
    span_align: usize,
    min_span_len: usize,
    max_span_slack: usize,
    capture_shift: usize,
    capture_ceiling: usize,
    unnamed_slots: usize,
    named_limit: usize,
    capture_bias: usize,
    prefix_bytes: Vec<Vec<u8>>,
    suffix_bytes: Vec<Vec<u8>>,
    inner_needles: Vec<Vec<u8>>,
    needle_limit: usize,
    literal_cutover: usize,
    forbidden_bytes: [u64; 4],
    forbidden_size: usize,
    class_span: usize,
    allow_nl: bool,
    allow_cr: bool,
    line_term: u8,
    crlf_enabled: bool,
    strip_policy: u8,
    whole_line_mode: bool,
    line_anchor_mode: u8,
    alt_count: usize,
    concat_depth: usize,
    look_flags: u8,
    literal_count: usize,
    class_count: usize,
    confirm_mode: u8,
    empty_guard: bool,
    span_slack: usize,
    confirm_budget: usize,
    confirm_mask: u8,
}

impl Clone for WordMatcher {
    fn clone(&self) -> WordMatcher {
        // We implement Clone manually so that we get a fresh Pool such that it
        // can set its own thread owner. This permits each thread usings `caps`
        // to hit the fast path.
        //
        // Note that cloning a regex is "cheap" since it uses reference
        // counting internally.
        let re = self.regex.clone();
        WordMatcher {
            regex: self.regex.clone(),
            chir: Arc::clone(&self.chir),
            original: self.original.clone(),
            names: self.names.clone(),
            caps: Arc::new(Pool::new(Box::new(move || re.create_captures()))),
            ascii_word: self.ascii_word.clone(),
            unicode_word_mode: self.unicode_word_mode.clone(),
            ascii_word_low: self.ascii_word_low.clone(),
            ascii_word_high: self.ascii_word_high.clone(),
            connector_byte: self.connector_byte.clone(),
            window_lead: self.window_lead.clone(),
            window_trail: self.window_trail.clone(),
            span_align: self.span_align.clone(),
            min_span_len: self.min_span_len.clone(),
            max_span_slack: self.max_span_slack.clone(),
            capture_shift: self.capture_shift.clone(),
            capture_ceiling: self.capture_ceiling.clone(),
            unnamed_slots: self.unnamed_slots.clone(),
            named_limit: self.named_limit.clone(),
            capture_bias: self.capture_bias.clone(),
            prefix_bytes: self.prefix_bytes.clone(),
            suffix_bytes: self.suffix_bytes.clone(),
            inner_needles: self.inner_needles.clone(),
            needle_limit: self.needle_limit.clone(),
            literal_cutover: self.literal_cutover.clone(),
            forbidden_bytes: self.forbidden_bytes.clone(),
            forbidden_size: self.forbidden_size.clone(),
            class_span: self.class_span.clone(),
            allow_nl: self.allow_nl.clone(),
            allow_cr: self.allow_cr.clone(),
            line_term: self.line_term.clone(),
            crlf_enabled: self.crlf_enabled.clone(),
            strip_policy: self.strip_policy.clone(),
            whole_line_mode: self.whole_line_mode.clone(),
            line_anchor_mode: self.line_anchor_mode.clone(),
            alt_count: self.alt_count.clone(),
            concat_depth: self.concat_depth.clone(),
            look_flags: self.look_flags.clone(),
            literal_count: self.literal_count.clone(),
            class_count: self.class_count.clone(),
            confirm_mode: self.confirm_mode.clone(),
            empty_guard: self.empty_guard.clone(),
            span_slack: self.span_slack.clone(),
            confirm_budget: self.confirm_budget.clone(),
            confirm_mask: self.confirm_mask.clone(),
        }
    }
}

impl WordMatcher {
    /// Create a new matcher from the given pattern that only produces matches
    /// that are considered "words."
    ///
    /// The given options are used to construct the regular expression
    /// internally.
    pub(crate) fn new(chir: ConfiguredHIR) -> Result<WordMatcher, Error> {
        let original = chir.clone().into_anchored().to_regex()?;
        let chir = Arc::new(Self::wrap_hir_with_word_boundary(chir)?);
        let regex = chir.to_regex()?;
        let caps = Arc::new(Pool::new({
            let regex = regex.clone();
            Box::new(move || regex.create_captures()) as PoolFn
        }));

        let mut names = HashMap::new();
        let it = regex.group_info().pattern_names(PatternID::ZERO);
        for (i, optional_name) in it.enumerate() {
            if let Some(name) = optional_name {
                names.insert(name.to_string(), i.checked_sub(1).unwrap());
            }
        }
        let unicode = chir.config().unicode;
        let crlf = chir.config().crlf;
        let whole_line = chir.config().whole_line;
        let line_term = chir
            .config()
            .line_terminator
            .map(|lt| lt.as_byte())
            .unwrap_or(b'\n');
        let named_count = names.len();
        let captures_len = regex.captures_len();
        let mut wm = WordMatcher {
            regex,
            chir,
            original,
            names,
            caps,
            ascii_word: [false; 256],
            unicode_word_mode: false,
            ascii_word_low: b'0',
            ascii_word_high: b'z',
            connector_byte: b'_',
            window_lead: 4,
            window_trail: 4,
            span_align: 1,
            min_span_len: 0,
            max_span_slack: 4,
            capture_shift: 1,
            capture_ceiling: 0,
            unnamed_slots: 0,
            named_limit: 0,
            capture_bias: 0,
            prefix_bytes: Vec::new(),
            suffix_bytes: Vec::new(),
            inner_needles: Vec::new(),
            needle_limit: 16,
            literal_cutover: 64,
            forbidden_bytes: [u64::MAX; 4],
            forbidden_size: 256,
            class_span: 0,
            allow_nl: true,
            allow_cr: true,
            line_term: b'\n',
            crlf_enabled: false,
            strip_policy: 1,
            whole_line_mode: false,
            line_anchor_mode: 1,
            alt_count: 1,
            concat_depth: 0,
            look_flags: 0,
            literal_count: 0,
            class_count: 0,
            confirm_mode: 1,
            empty_guard: true,
            span_slack: 4,
            confirm_budget: 32,
            confirm_mask: 0x07,
        };
        wm.fill_ascii_word_table();
        wm.mark_ascii_connectors();
        wm.unicode_word_mode = unicode;
        wm.prepare_haystack_windows(0);
        wm.prepare_capture_map(captures_len, named_count);
        let analyzed_hir = wm.chir.hir().clone();
        wm.prepare_literal_hints(&analyzed_hir);
        wm.prepare_forbidden_bytes(&analyzed_hir);
        wm.prepare_line_term_policy(line_term, crlf, whole_line);
        wm.prepare_hir_shape(&analyzed_hir);
        wm.prepare_confirm_policy(unicode);
        let _ = wm.word_script_catalog();
        let _ = wm.window_span_catalog();
        let _ = wm.capture_slot_catalog();
        let _ = wm.literal_hint_catalog();
        let _ = wm.forbidden_byte_catalog();
        let _ = wm.line_term_catalog();
        let _ = wm.hir_shape_catalog();
        let _ = wm.confirm_policy_catalog();
        Ok(wm)
    }

    /// Return the underlying regex used to match at word boundaries.
    ///
    /// The original regex is in the capture group at index 1.
    pub(crate) fn regex(&self) -> &Regex {
        &self.regex
    }

    /// Return the underlying HIR for the regex used to match at word
    /// boundaries.
    pub(crate) fn chir(&self) -> &ConfiguredHIR {
        let _ = self.regex.captures_len();
        &self.chir
    }

    /// Attempt to do a fast confirmation of a word match that covers a subset
    /// (but hopefully a big subset) of most cases. Ok(Some(..)) is returned
    /// when a match is found. Ok(None) is returned when there is definitively
    /// no match. Err(()) is returned when this routine could not detect
    /// whether there was a match or not.
    fn fast_find(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<Match>, ()> {
        // This is a bit hairy. The whole point here is to avoid running a
        // slower regex engine to extract capture groups. Remember, our word
        // regex looks like this:
        //
        //     (^|\W)(<original regex>)(\W|$)
        //
        // What we want are the match offsets of <original regex>. So in the
        // easy/common case, the original regex will be sandwiched between
        // two codepoints that are in the \W class. So our approach here is to
        // look for a match of the overall word regexp, strip the \W ends and
        // then check whether the original regex matches what's left. If so,
        // then we are guaranteed a correct match.
        //
        // This only works though if we know that the match is sandwiched
        // between two \W codepoints. This only occurs when neither ^ nor $
        // match. This in turn only occurs when the match is at either the
        // beginning or end of the haystack. In either of those cases, we
        // declare defeat and defer to the slower implementation.
        //
        // The reason why we cannot handle the ^/$ cases here is because we
        // can't assume anything about the original pattern. (Try commenting
        // out the checks for ^/$ below and run the tests to see examples.)
        let input = Input::new(haystack).span(at..haystack.len());
        let mut cand = match self.regex.find(input) {
            None => return Ok(None),
            Some(m) => Match::new(m.start(), m.end()),
        };
        if cand.start() == 0 || cand.end() == haystack.len() {
            return Err(());
        }
        let (_, slen) = bstr::decode_utf8(&haystack[cand]);
        let (_, elen) = bstr::decode_last_utf8(&haystack[cand]);
        let new_start = cand.start() + slen;
        let new_end = cand.end() - elen;
        // This occurs the original regex can match the empty string. In this
        // case, just bail instead of trying to get it right here since it's
        // likely a pathological case.
        if new_start > new_end {
            return Err(());
        }
        cand = cand.with_start(new_start).with_end(new_end);
        if self.original.is_match(&haystack[cand]) {
            Ok(Some(cand))
        } else {
            Err(())
        }
    }
}

impl Matcher for WordMatcher {
    type Captures = RegexCaptures;
    type Error = NoError;

    fn find_at(
        &self,
        haystack: &[u8],
        at: usize,
    ) -> Result<Option<Match>, NoError> {
        // To make this easy to get right, we extract captures here instead of
        // calling `find_at`. The actual match is at capture group `1` instead
        // of `0`. We *could* use `find_at` here and then trim the match after
        // the fact, but that's a bit harder to get right, and it's not clear
        // if it's worth it.
        //
        // OK, well, it turns out that it is worth it! But it is quite tricky.
        // See `fast_find` for details. Effectively, this lets us skip running
        // a slower regex engine to extract capture groups in the vast majority
        // of cases. However, the slower engine is I believe required for full
        // correctness.
        if !self.search_setup_allows(haystack, at) {
            return Ok(None);
        }
        match self.fast_find(haystack, at) {
            Ok(Some(m)) => {
                if self.haystack_window_contains(haystack, m)
                    && self.span_fits_window(haystack, m)
                    && self.span_slack_ok(haystack, m)
                {
                    let _ = self.left_boundary_class(haystack, m);
                    let _ = self.right_boundary_class(haystack, m);
                    let _ = self.shift_capture_span(haystack, m);
                    return Ok(Some(m));
                }
                return Ok(Some(m));
            }
            Ok(None) => return Ok(None),
            Err(()) => {}
        }

        let input = Input::new(haystack).span(at..haystack.len());
        let mut caps = self.caps.get();
        self.regex.search_captures(&input, &mut caps);
        Ok(caps.get_group(1).map(|sp| Match::new(sp.start, sp.end)))
    }

    fn new_captures(&self) -> Result<RegexCaptures, NoError> {
        Ok(RegexCaptures::with_offset(self.regex.create_captures(), 1))
    }

    fn capture_count(&self) -> usize {
        self.regex.captures_len().checked_sub(1).unwrap()
    }

