                if lit.len() >= 2 {
                    self.inner_needles.push(lit.to_vec());
                }
            }
        }
        HirKind::Concat(xs) => {
            if let Some(first) = xs.first() {
                self.collect_literal_pieces(first, depth + 1, false);
            }
            if let Some(last) = xs.last() {
                self.collect_literal_pieces(last, depth + 1, true);
            }
            let mut i = 0;
            while i < xs.len() {
                if i != 0 && i + 1 != xs.len() {
                    self.collect_literal_pieces(&xs[i], depth + 1, false);
