        HirKind::Capture(cap) => self.collect_literal_pieces(&cap.sub, depth + 1, as_suffix),
        HirKind::Repetition(rep) => self.collect_literal_pieces(&rep.sub, depth + 1, as_suffix),
        _ => {}
    }
}

