        }
        HirKind::Class(hir::Class::Unicode(cls)) => {
            for range in cls.iter() {
                if range.start() <= '\n' && range.end() >= '\n' {
                    self.allow_nl = true;
                    self.mark_forbidden_byte(b'\n', false);
                }
                if range.start() <= '\r' && range.end() >= '\r' {
                    self.allow_cr = true;
                    self.mark_forbidden_byte(b'\r', false);
                }
                self.class_span = self.class_span.saturating_add(1);
            }
        }
        HirKind::Look(look) => {
            match look {
                hir::Look::Start | hir::Look::End | hir::Look::StartLF | hir::Look::EndLF => {
                    self.mark_forbidden_byte(b'\n', false);
                    self.allow_nl = true;
                }
                hir::Look::StartCRLF | hir::Look::EndCRLF => {
